import { corsHeaders, errorResponse, getCallerId, jsonResponse, randomState, serviceClient } from '../_shared/oauth.ts';
import { getCredential } from '../_shared/credentials.ts';

// Permissions needed to: list Pages, read/publish Page posts, and publish to
// a linked Instagram Business account. `business_management` is required if
// the Page is owned by a Business Manager rather than the user directly.
const META_SCOPES = [
  'pages_show_list',
  'pages_read_engagement',
  'pages_manage_posts',
  'pages_manage_metadata',
  'instagram_basic',
  'instagram_content_publish',
  'business_management',
].join(',');

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') return new Response(null, { status: 200, headers: corsHeaders });
  if (req.method !== 'POST') return errorResponse('Method not allowed', 405);

  const functionsUrl = Deno.env.get('SUPABASE_URL')!.replace('.supabase.co', '.supabase.co/functions/v1');
  const supabase = serviceClient();
  const appId = await getCredential(supabase, 'meta_app_id');
  if (!appId) return errorResponse('Meta App ID is not configured. Set it in Settings > Integrations.', 500);
  // Apps set up under "Facebook Login for Business" (as opposed to classic
  // Facebook Login) require a config_id from a Login Configuration instead
  // of a plain scope list — the classic scope-based dialog fails silently
  // (generic "Sorry, something went wrong") for these apps.
  const configId = await getCredential(supabase, 'meta_config_id');

  const callerId = await getCallerId(supabase, req);
  if (!callerId) return errorResponse('Unauthorized', 401);

  const { workspace_id } = await req.json().catch(() => ({}));
  if (!workspace_id) return errorResponse('workspace_id is required', 400);

  const { data: membership } = await supabase
    .from('workspace_members')
    .select('id')
    .eq('workspace_id', workspace_id)
    .eq('user_id', callerId)
    .maybeSingle();
  if (!membership) return errorResponse('Forbidden', 403);

  const state = randomState();
  const { error } = await supabase.from('oauth_states').insert({
    state,
    workspace_id,
    user_id: callerId,
    platform: 'meta',
  });
  if (error) return errorResponse('Could not start OAuth flow', 500);

  const redirectUri = `${functionsUrl}/meta-oauth-callback`;
  const authorizeUrl = new URL('https://www.facebook.com/v21.0/dialog/oauth');
  authorizeUrl.searchParams.set('client_id', appId);
  authorizeUrl.searchParams.set('redirect_uri', redirectUri);
  authorizeUrl.searchParams.set('state', state);
  authorizeUrl.searchParams.set('response_type', 'code');
  if (configId) {
    // Facebook Login for Business: pass the Login Configuration ID instead
    // of scope (Meta recommends omitting scope entirely in this mode).
    authorizeUrl.searchParams.set('config_id', configId);
  } else {
    authorizeUrl.searchParams.set('scope', META_SCOPES);
  }

  return jsonResponse({ url: authorizeUrl.toString() });
});

import { createClient, SupabaseClient } from 'npm:@supabase/supabase-js@2.57.4';
import { getCredential } from './credentials.ts';

export const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization, X-Client-Info, Apikey',
};

export function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  });
}

export function errorResponse(message: string, status = 400): Response {
  return jsonResponse({ error: message }, status);
}

/** Redirect back into the app's Connected Accounts page with an outcome.
 * Resolves the base URL from Settings > Integrations first, falling back
 * to the APP_URL env var if nothing's been saved there yet. */
export async function redirectToApp(supabase: SupabaseClient, params: Record<string, string>): Promise<Response> {
  const appUrl = (await getCredential(supabase, 'app_url')) ?? '';
  const url = new URL(`${appUrl.replace(/\/$/, '')}/accounts`);
  for (const [key, value] of Object.entries(params)) url.searchParams.set(key, value);
  return new Response(null, { status: 302, headers: { Location: url.toString() } });
}

export function serviceClient(): SupabaseClient {
  const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
  const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
  return createClient(supabaseUrl, serviceKey, { auth: { autoRefreshToken: false, persistSession: false } });
}

/** Verifies the caller's bearer token and returns their user id, or null. */
export async function getCallerId(supabase: SupabaseClient, req: Request): Promise<string | null> {
  const authHeader = req.headers.get('Authorization');
  if (!authHeader?.startsWith('Bearer ')) return null;
  const { data, error } = await supabase.auth.getUser(authHeader.slice(7));
  if (error || !data.user) return null;
  return data.user.id;
}

export function randomState(): string {
  return crypto.randomUUID().replace(/-/g, '') + crypto.randomUUID().replace(/-/g, '');
}

import { SupabaseClient } from 'npm:@supabase/supabase-js@2.57.4';

/** Known credential keys the Settings > Integrations page can save, and the
 * env var each falls back to if nothing's been saved in the DB yet (so
 * existing dashboard/CLI-configured secrets keep working). */
const ENV_FALLBACK: Record<string, string> = {
  meta_app_id: 'META_APP_ID',
  meta_app_secret: 'META_APP_SECRET',
  meta_config_id: 'META_CONFIG_ID',
  linkedin_client_id: 'LINKEDIN_CLIENT_ID',
  linkedin_client_secret: 'LINKEDIN_CLIENT_SECRET',
  app_url: 'APP_URL',
};

/** Resolves one credential: DB value (set from the app) takes priority,
 * falling back to the matching env var. Returns null if neither is set. */
export async function getCredential(supabase: SupabaseClient, key: string): Promise<string | null> {
  const { data } = await supabase.from('platform_credentials').select('value').eq('key', key).maybeSingle();
  if (data?.value) return data.value;
  const envKey = ENV_FALLBACK[key];
  return envKey ? Deno.env.get(envKey) ?? null : null;
}

/** Resolves several credentials in one round trip. */
export async function getCredentials(supabase: SupabaseClient, keys: string[]): Promise<Record<string, string | null>> {
  const { data } = await supabase.from('platform_credentials').select('key, value').in('key', keys);
  const fromDb = new Map((data ?? []).map((row) => [row.key as string, row.value as string]));
  const result: Record<string, string | null> = {};
  for (const key of keys) {
    result[key] = fromDb.get(key) || (ENV_FALLBACK[key] ? Deno.env.get(ENV_FALLBACK[key]) ?? null : null);
  }
  return result;
}
